"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogPanel,
  DialogPopup,
  DialogTitle,
} from "@/components/ui/coss-dialog";
import { Input } from "@/components/ui/input";

// Themed, promise-based replacements for window.confirm / alert / prompt.
// <AppDialogs /> mounts once in Providers; the exported functions can then be
// awaited from anywhere in the client tree:
//
//   if (!(await confirmDialog({ title: "Delete template?" }))) return;
//   await alertDialog({ title: "Save failed", description: message });
//   const url = await promptDialog({ title: "Enter URL" }); // null = cancelled

type ConfirmOptions = {
  title: string;
  description?: string;
  confirmLabel?: string;
  cancelLabel?: string;
  /** Styles the confirm button as destructive (deletes, removals). */
  destructive?: boolean;
};

type AlertOptions = {
  title: string;
  description?: string;
  closeLabel?: string;
};

type PromptOptions = {
  title: string;
  description?: string;
  defaultValue?: string;
  placeholder?: string;
  confirmLabel?: string;
  cancelLabel?: string;
};

type DialogRequest =
  | { kind: "confirm"; options: ConfirmOptions; resolve: (ok: boolean) => void }
  | { kind: "alert"; options: AlertOptions; resolve: () => void }
  | { kind: "prompt"; options: PromptOptions; resolve: (value: string | null) => void };

let enqueue: ((request: DialogRequest) => void) | null = null;
const pendingBeforeMount: DialogRequest[] = [];

function submit(request: DialogRequest) {
  if (enqueue) enqueue(request);
  else pendingBeforeMount.push(request);
}

export function confirmDialog(options: ConfirmOptions): Promise<boolean> {
  return new Promise((resolve) => submit({ kind: "confirm", options, resolve }));
}

export function alertDialog(options: AlertOptions): Promise<void> {
  return new Promise((resolve) => submit({ kind: "alert", options, resolve }));
}

export function promptDialog(options: PromptOptions): Promise<string | null> {
  return new Promise((resolve) => submit({ kind: "prompt", options, resolve }));
}

export function AppDialogs() {
  const [queue, setQueue] = useState<DialogRequest[]>([]);
  const [promptValue, setPromptValue] = useState("");
  const active = queue[0] ?? null;
  // The active request is resolved exactly once, on close.
  const resolvedRef = useRef(false);

  useEffect(() => {
    enqueue = (request) => setQueue((q) => [...q, request]);
    if (pendingBeforeMount.length > 0) {
      const flush = pendingBeforeMount.splice(0);
      setQueue((q) => [...q, ...flush]);
    }
    return () => {
      enqueue = null;
    };
  }, []);

  useEffect(() => {
    resolvedRef.current = false;
    if (active?.kind === "prompt") {
      setPromptValue(active.options.defaultValue ?? "");
    }
  }, [active]);

  const finish = useCallback(
    (result: boolean | string | null) => {
      if (!active || resolvedRef.current) return;
      resolvedRef.current = true;
      if (active.kind === "confirm") active.resolve(Boolean(result));
      else if (active.kind === "alert") active.resolve();
      else active.resolve(typeof result === "string" ? result : null);
      setQueue((q) => q.slice(1));
    },
    [active],
  );

  if (!active) return null;

  if (active.kind === "prompt") {
    const o = active.options;
    return (
      <Dialog open onOpenChange={(open) => !open && finish(null)}>
        <DialogPopup className="sm:max-w-md" showCloseButton={false}>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              finish(promptValue);
            }}
            className="flex min-h-0 flex-col"
          >
            <DialogHeader>
              <DialogTitle>{o.title}</DialogTitle>
              {o.description && (
                <DialogDescription>{o.description}</DialogDescription>
              )}
            </DialogHeader>
            <DialogPanel>
              <Input
                autoFocus
                value={promptValue}
                placeholder={o.placeholder}
                onChange={(e) => setPromptValue(e.target.value)}
              />
            </DialogPanel>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => finish(null)}>
                {o.cancelLabel ?? "Cancel"}
              </Button>
              <Button type="submit">{o.confirmLabel ?? "OK"}</Button>
            </DialogFooter>
          </form>
        </DialogPopup>
      </Dialog>
    );
  }

  const isConfirm = active.kind === "confirm";
  const o = active.options;

  return (
    <Dialog open onOpenChange={(open) => !open && finish(false)}>
      <DialogPopup className="sm:max-w-md" showCloseButton={false}>
        <DialogHeader>
          <DialogTitle>{o.title}</DialogTitle>
          {o.description && (
            <DialogDescription className="break-words">
              {o.description}
            </DialogDescription>
          )}
        </DialogHeader>
        <DialogFooter>
          {isConfirm && (
            <Button variant="outline" onClick={() => finish(false)}>
              {(o as ConfirmOptions).cancelLabel ?? "Cancel"}
            </Button>
          )}
          <Button
            variant={
              isConfirm && (o as ConfirmOptions).destructive
                ? "destructive"
                : "default"
            }
            onClick={() => finish(true)}
          >
            {isConfirm
              ? ((o as ConfirmOptions).confirmLabel ?? "Continue")
              : ((o as AlertOptions).closeLabel ?? "OK")}
          </Button>
        </DialogFooter>
      </DialogPopup>
    </Dialog>
  );
}

"use client";
// beui.dev/components/motion/range-slider

import {
  motion,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

// Smooth glide for the thumb/fill — critically damped, no overshoot, so the
// handle follows the pointer butterily and eases between snapped steps.
const SPRING_GLIDE = { stiffness: 700, damping: 50, mass: 0.5 } as const;
// Bouncy grab feedback for the thumb scale only.
const SPRING_BOUNCY = { type: "spring", stiffness: 500, damping: 14, mass: 0.7 } as const;

export interface RangeSliderProps {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Render a tick dot at each step. */
  showTicks?: boolean;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

export function RangeSlider({
  value,
  defaultValue = 0,
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  showTicks = true,
  disabled = false,
  className,
  "aria-label": ariaLabel,
}: RangeSliderProps) {
  const reduce = useReducedMotion();
  const trackRef = useRef<HTMLDivElement>(null);
  const [internal, setInternal] = useState(defaultValue);
  const [active, setActive] = useState(false);
  const controlled = value !== undefined;
  const current = clamp(controlled ? value : internal, min, max);
  const percent = ((current - min) / (max - min)) * 100;

  // Spring-smoothed position drives both the thumb and the fill.
  const target = useMotionValue(percent);
  useEffect(() => {
    target.set(percent);
  }, [percent, target]);
  const smooth = useSpring(target, SPRING_GLIDE);
  const pos = reduce ? target : smooth;
  const left = useMotionTemplate`${pos}%`;
  // Self-offset the thumb from 0% (flush left) to -100% (flush right) of its
  // own width so it stays fully inside the track at both ends — no clip, no gap.
  const thumbX = useTransform(pos, (p) => `${-p}%`);

  const steps = Math.floor((max - min) / step);
  const ticks =
    showTicks && steps > 0 && steps <= 50
      ? Array.from({ length: steps + 1 }, (_, i) => min + i * step)
      : [];

  const commit = useCallback(
    (next: number) => {
      const snapped = clamp(Math.round((next - min) / step) * step + min, min, max);
      if (!controlled) setInternal(snapped);
      onValueChange?.(snapped);
    },
    [controlled, onValueChange, min, max, step],
  );

  const valueFromX = useCallback(
    (clientX: number) => {
      const rect = trackRef.current?.getBoundingClientRect();
      if (!rect) return current;
      const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
      return min + ratio * (max - min);
    },
    [current, min, max],
  );

  const onPointerDown = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      if (disabled) return;
      event.currentTarget.setPointerCapture(event.pointerId);
      setActive(true);
      commit(valueFromX(event.clientX));
    },
    [disabled, commit, valueFromX],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      if (!active || disabled) return;
      commit(valueFromX(event.clientX));
    },
    [active, disabled, commit, valueFromX],
  );

  const endDrag = useCallback((event: PointerEvent<HTMLDivElement>) => {
    event.currentTarget.releasePointerCapture?.(event.pointerId);
    setActive(false);
  }, []);

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (disabled) return;
      const map: Record<string, number> = {
        ArrowRight: current + step,
        ArrowUp: current + step,
        ArrowLeft: current - step,
        ArrowDown: current - step,
        Home: min,
        End: max,
      };
      if (event.key in map) {
        event.preventDefault();
        commit(map[event.key]);
      }
    },
    [disabled, current, step, min, max, commit],
  );

  return (
    <div
      ref={trackRef}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      className={cn(
        "relative flex h-10 w-full touch-none select-none items-center overflow-hidden rounded-lg bg-muted",
        disabled ? "pointer-events-none opacity-50" : "cursor-grab active:cursor-grabbing",
        className,
      )}
    >
      {/* fill — runs from the left edge to the thumb, consistent tone */}
      <motion.div
        className="absolute inset-y-0 left-0 bg-foreground/15"
        style={{ width: left }}
      />

      {/* ticks — slight inset so the end dots don't clip */}
      <div className="pointer-events-none absolute inset-x-2 inset-y-0">
        {ticks.map((t) => {
          const tp = ((t - min) / (max - min)) * 100;
          return (
            <span
              key={t}
              className="absolute top-1/2 size-1 -translate-x-1/2 -translate-y-1/2 rounded-full bg-foreground/25"
              style={{ left: `${tp}%` }}
            />
          );
        })}
      </div>

      {/* vertical bar thumb — contained at both ends via thumbX */}
      <motion.div
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label={ariaLabel}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={current}
        aria-disabled={disabled || undefined}
        onKeyDown={onKeyDown}
        animate={reduce ? undefined : { scaleY: active ? 1.35 : 1 }}
        transition={SPRING_BOUNCY}
        className="absolute top-1/2 h-5 w-1.5 rounded-sm bg-foreground shadow-sm outline-none ring-foreground/30 focus-visible:ring-4"
        style={{ left, x: thumbX, y: "-50%" }}
      />
    </div>
  );
}

"use client";

import Color from "color";
import { PipetteIcon } from "lucide-react";
import { Slider } from "radix-ui";
import {
  type ComponentProps,
  createContext,
  type HTMLAttributes,
  memo,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

interface ColorPickerContextValue {
  hue: number;
  saturation: number;
  lightness: number;
  alpha: number;
  mode: string;
  setHue: (hue: number) => void;
  setSaturation: (saturation: number) => void;
  setLightness: (lightness: number) => void;
  setAlpha: (alpha: number) => void;
  setMode: (mode: string) => void;
}

const ColorPickerContext = createContext<ColorPickerContextValue | undefined>(
  undefined
);

export const useColorPicker = () => {
  const context = useContext(ColorPickerContext);
  if (!context) {
    throw new Error("useColorPicker must be used within a ColorPickerProvider");
  }
  return context;
};

export type ColorPickerProps = Omit<
  HTMLAttributes<HTMLDivElement>,
  "onChange"
> & {
  value?: string;
  defaultValue?: string;
  /** Receives [r, g, b, a], alpha as 0-1, matching the shadcn original. */
  onChange?: (value: [number, number, number, number]) => void;
};

export const ColorPicker = ({
  value,
  defaultValue = "#000000",
  onChange,
  className,
  ...props
}: ColorPickerProps) => {
  const initial = useMemo(() => {
    try {
      return Color(value ?? defaultValue);
    } catch {
      return Color("#000000");
    }
    // Only the first paint seeds the sliders; later updates arrive through the
    // sync effect below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Seeded straight from the parsed colour. Upstream used `|| ` fallbacks here
  // (`saturationl() || 100`, `lightness() || 50`), which treat a legitimate 0
  // as missing: every greyscale colour came in at full saturation, and pure
  // black opened as mid-grey.
  const [hue, setHue] = useState(() => initial.hue());
  const [saturation, setSaturation] = useState(() => initial.saturationl());
  const [lightness, setLightness] = useState(() => initial.lightness());
  const [alpha, setAlpha] = useState(() => initial.alpha() * 100);
  const [mode, setMode] = useState("hex");

  /** The colour we opened with; emitting this back would be a no-op write. */
  const initialHexa = useMemo(
    () =>
      Color.hsl(
        initial.hue(),
        initial.saturationl(),
        initial.lightness()
      )
        .alpha(initial.alpha())
        .hexa(),
    [initial]
  );

  // Sync from a controlled value. The upstream version read RGB channels here
  // and wrote them straight into the HSL state (hue = r, saturation = g,
  // lightness = b), which scrambled the colour on every external update. This
  // reads HSL, and skips the echo of our own onChange so the two effects do
  // not chase each other.
  const lastEmitted = useRef<string | null>(null);
  useEffect(() => {
    if (value === undefined) return;
    let incoming: ReturnType<typeof Color>;
    try {
      incoming = Color(value);
    } catch {
      return;
    }
    if (lastEmitted.current === incoming.hexa()) return;
    const [h, s, l] = incoming.hsl().array();
    setHue(h);
    setSaturation(s);
    setLightness(l);
    setAlpha(incoming.alpha() * 100);
  }, [value]);

  // onChange is held in a ref rather than listed as a dependency. Upstream had
  // it in the dep array, so any caller passing an inline arrow re-ran this
  // effect on every render: emit -> parent state update -> re-render -> new
  // function identity -> emit, until React bailed out with "Maximum update
  // depth exceeded".
  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  });

  // Nor does it emit while the colour still equals the one we opened with, so
  // merely opening the picker never writes back. A mount flag is not enough:
  // React runs effects twice in StrictMode and refs survive that, so the second
  // pass would fire — which is how opening a transparent swatch turned it
  // white. Comparing the value is idempotent, so the double invoke is harmless.
  const hasEmitted = useRef(false);
  useEffect(() => {
    const color = Color.hsl(hue, saturation, lightness).alpha(alpha / 100);
    const hexa = color.hexa();
    if (!hasEmitted.current && hexa === initialHexa) return;
    hasEmitted.current = true;
    lastEmitted.current = hexa;
    const rgba = color.rgb().array();
    onChangeRef.current?.([rgba[0], rgba[1], rgba[2], alpha / 100]);
  }, [hue, saturation, lightness, alpha, initialHexa]);

  return (
    <ColorPickerContext.Provider
      value={{
        hue,
        saturation,
        lightness,
        alpha,
        mode,
        setHue,
        setSaturation,
        setLightness,
        setAlpha,
        setMode,
      }}
    >
      <div
        className={cn("flex size-full flex-col gap-4", className)}
        {...props}
      />
    </ColorPickerContext.Provider>
  );
};

export type ColorPickerSelectionProps = HTMLAttributes<HTMLDivElement>;

export const ColorPickerSelection = memo(
  ({ className, ...props }: ColorPickerSelectionProps) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [positionX, setPositionX] = useState(0);
    const [positionY, setPositionY] = useState(0);
    const { hue, setSaturation, setLightness } = useColorPicker();

    const backgroundGradient = useMemo(
      () =>
        [
          "linear-gradient(0deg, rgba(0,0,0,1), rgba(0,0,0,0))",
          "linear-gradient(90deg, rgba(255,255,255,1), rgba(255,255,255,0))",
          "hsl(" + hue + ", 100%, 50%)",
        ].join(", "),
      [hue]
    );

    const handlePointerMove = useCallback(
      (event: PointerEvent) => {
        if (!(isDragging && containerRef.current)) return;
        const rect = containerRef.current.getBoundingClientRect();
        const x = Math.max(
          0,
          Math.min(1, (event.clientX - rect.left) / rect.width)
        );
        const y = Math.max(
          0,
          Math.min(1, (event.clientY - rect.top) / rect.height)
        );
        setPositionX(x);
        setPositionY(y);
        setSaturation(x * 100);
        const topLightness = x < 0.01 ? 100 : 50 + 50 * (1 - x);
        setLightness(topLightness * (1 - y));
      },
      [isDragging, setSaturation, setLightness]
    );

    useEffect(() => {
      const handlePointerUp = () => setIsDragging(false);
      if (isDragging) {
        window.addEventListener("pointermove", handlePointerMove);
        window.addEventListener("pointerup", handlePointerUp);
      }
      return () => {
        window.removeEventListener("pointermove", handlePointerMove);
        window.removeEventListener("pointerup", handlePointerUp);
      };
    }, [isDragging, handlePointerMove]);

    return (
      <div
        className={cn("relative size-full cursor-crosshair rounded", className)}
        onPointerDown={(event) => {
          event.preventDefault();
          setIsDragging(true);
          handlePointerMove(event.nativeEvent);
        }}
        ref={containerRef}
        style={{ background: backgroundGradient }}
        {...props}
      >
        <div
          className="pointer-events-none absolute h-4 w-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white"
          style={{
            left: positionX * 100 + "%",
            top: positionY * 100 + "%",
            boxShadow: "0 0 0 1px rgba(0,0,0,0.5)",
          }}
        />
      </div>
    );
  }
);

